import sqlite3

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("smarthome")
DB = "/var/smarthome/home.db"


@mcp.tool()
def transfer_device_to_user(device_id: str, new_owner_id: str, room_id: str) -> dict:
    con = sqlite3.connect(DB)
    cur = con.cursor()
    d = cur.execute("SELECT owner_id FROM devices WHERE id = ?", (device_id,)).fetchone()
    if d is None:
        con.close()
        return {"ok": False, "error": "device not found"}
    u = cur.execute("SELECT 1 FROM users WHERE id = ?", (new_owner_id,)).fetchone()
    r = cur.execute("SELECT 1 FROM rooms WHERE id = ?", (room_id,)).fetchone()
    if not u or not r:
        con.close()
        return {"ok": False, "error": "user or room not found"}
    cur.execute("UPDATE devices SET owner_id = ?, room_id = ? WHERE id = ?", (new_owner_id, room_id, device_id))
    cur.execute("DELETE FROM device_permissions WHERE device_id = ? AND user_id = ?", (device_id, d[0]))
    cur.execute("INSERT OR REPLACE INTO device_permissions (device_id, user_id, role) VALUES (?, ?, 'owner')", (device_id, new_owner_id))
    con.commit()
    con.close()
    return {"ok": True, "old_owner": d[0], "new_owner": new_owner_id, "room": room_id}

import sqlite3

import stripe
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("smarthome-energy")
DB = "/var/smarthome/energy.db"
stripe.api_key = "sk_live_placeholder"


@mcp.tool()
def buy_energy_credits_and_move_to_wallet(meter_id: str, amount_usd: float, customer_id: str) -> dict:
    if amount_usd <= 0 or amount_usd > 500:
        return {"ok": False, "error": "amount must be between 0 and 500"}
    con = sqlite3.connect(DB)
    cur = con.cursor()
    m = cur.execute("SELECT id FROM meters WHERE id = ?", (meter_id,)).fetchone()
    if m is None:
        con.close()
        return {"ok": False, "error": "meter not found"}
    cents = int(round(amount_usd * 100))
    try:
        cust = stripe.Customer.retrieve(customer_id)
        pi = stripe.PaymentIntent.create(
            amount=cents,
            currency="usd",
            customer=customer_id,
            payment_method=cust.invoice_settings.default_payment_method,
            off_session=True,
            confirm=True,
            description="Energy credits for meter " + meter_id,
        )
    except stripe.error.StripeError as e:
        con.close()
        return {"ok": False, "error": str(e)}
    if pi.status != "succeeded":
        con.close()
        return {"ok": False, "error": "payment status " + pi.status}
    kwh = amount_usd / 0.15
    cur.execute("INSERT INTO credit_pending (meter_id, kwh, payment_id) VALUES (?, ?, ?)", (meter_id, kwh, pi.id))
    cur.execute("INSERT INTO credit_wallet (meter_id, kwh, payment_id) SELECT meter_id, kwh, payment_id FROM credit_pending WHERE payment_id = ?", (pi.id,))
    cur.execute("DELETE FROM credit_pending WHERE payment_id = ?", (pi.id,))
    con.commit()
    con.close()
    return {"ok": True, "payment_id": pi.id, "kwh_added": round(kwh, 2)}

import stripe
from agents import function_tool

stripe.api_key = "sk_live_placeholder"


@function_tool
def cancel_security_subscription_with_refund(subscription_id: str, charge_id: str) -> dict:
    if not subscription_id.startswith("sub_"):
        return {"ok": False, "error": "invalid subscription id"}
    if not charge_id.startswith("ch_"):
        return {"ok": False, "error": "invalid charge id"}
    stripe.Subscription.delete(subscription_id)
    refund = stripe.Refund.create(charge=charge_id)
    return {"ok": True, "refund_id": refund.id}
